const core = global.get('core');
const cronSyncMessages = global.get('cronSyncMessages');
const refreshCueCache = global.get('refreshCueCache');
const refreshAllReferencedCues = global.get('refreshAllReferencedCues');

return (async () => {
    // Found via a real robustness review: this had no try/catch at all - a failure here
    // (e.g. the OSC port still held by a not-yet-released prior process) previously surfaced
    // only as a raw uncaught-rejection stack trace, with scheduling left silently disarmed
    // (armed stays false forever) and nothing distinguishing that from "QLab just isn't open
    // yet" anywhere an operator would see. Deliberately still fails fast/aborts startup here
    // (no in-process retry) - launchd's KeepAlive (see deploy/launchd/) is the actual
    // recovery mechanism; this just makes the cause unmistakable when it restarts.
    try {
        await core.osc.client.open();
        await core.health.start();
    } catch (err) {
        node.error(`Startup FAILED - could not open the OSC connection / arm health monitoring, scheduling will NOT run until this is fixed: ${err.message}`);
        return null;
    }

    const directives = core.scheduling.cronSync.rebuildAll(core.db.connection);
    const msgs = cronSyncMessages.toCronPlusMessages(directives);

    node.log(`Startup: rebuilding ${msgs.length} cron-plus directive(s)`);

    // Best-effort cue_cache warm-up for every referenced cue, so the webapp has zone/
    // duration data to display even before any schedule is created/edited post-boot.
    const results = await refreshAllReferencedCues(core, refreshCueCache);
    for (const [cueNumber, result] of Object.entries(results)) {
        if (result && result.error) {
            node.warn(`cue_cache warm-up failed for ${cueNumber}: ${result.error}`);
        }
        if (result && Array.isArray(result.unmappedLeafCues) && result.unmappedLeafCues.length > 0) {
            for (const { cueNumber: unmappedCue, patchId } of result.unmappedLeafCues) {
                node.warn(`cue ${unmappedCue} (referenced via ${cueNumber}) is on patch ${patchId}, which isn't mapped to any zone in config/audio-patch-map.json`);
            }
        }
    }

    // Every zone a REAL schedule/VOG cue actually resolves to must have a duck/unduck
    // entry in config/audio-patch-map.json (see lib/zones/audioPatchMap.js) - otherwise
    // onZoneTransition silently no-ops for that zone (see lib/index.js) and music simply
    // never ducks there, with nothing in the log to explain why. Surfaced loudly
    // (node.error, not a thrown exception) rather than aborting startup outright - a
    // config gap for one zone shouldn't disarm every OTHER correctly-configured zone's
    // schedules too.
    const resolvedZones = new Set();
    for (const result of Object.values(results)) {
        if (result && Array.isArray(result.zones)) {
            for (const zone of result.zones) resolvedZones.add(zone);
        }
    }
    const missingZones = Array.from(resolvedZones).filter((zone) => !core.zones.config.has(zone));
    if (missingZones.length > 0) {
        node.error(
            `Startup: zone(s) missing duck/unduck config in config/audio-patch-map.json - ` +
            `music will silently never duck there: ${missingZones.join(', ')}`
        );
    }

    return [msgs];
})();

const core = global.get('core');
const refreshCueCache = global.get('refreshCueCache');

if (!msg.topic || !msg.topic.startsWith('sched-')) {
    // command-response / status messages from cron-plus itself, not a fire event - ignore
    return null;
}

const scheduleId = Number(msg.topic.replace('sched-', ''));
const schedule = core.db.schedules.getById(core.db.connection, scheduleId);

if (!schedule) {
    node.warn(`No schedule found in DB for ${msg.topic} (deleted since being scheduled?)`);
    return null;
}

if (!core.health.isArmed()) {
    node.warn(`Skipping ${schedule.qlabCueNumber}: QLab not confirmed live (health state: ${core.health.getState()})`);
    return null;
}

return (async () => {
    // Live-resolve zones/duration/per-zone play details (also refreshes cue_cache as a side
    // effect) rather than trusting a possibly-stale cache entry for a collision decision.
    // zoneDetails (each zone's own specific child cue/duration/uniqueId - see
    // zoneResolver.resolveZoneDetailsForCue) is what lets zoneQueueEngine fire and free each
    // zone of a multi-zone Group cue completely independently of the others.
    const cue = await refreshCueCache(core, schedule.qlabCueNumber);
    if (cue.error) {
        node.warn(`Skipping ${schedule.qlabCueNumber}: failed to resolve zones/duration live (${cue.error})`);
        return null;
    }

    const { fired } = await core.queue.enqueue({
        id: `sched-${scheduleId}-${Date.now()}`,
        dedupeKey: `schedule-${scheduleId}`,
        scheduleId,
        cueNumber: schedule.qlabCueNumber,
        qlabInternalId: cue.qlabInternalId,
        zones: cue.zones,
        zoneDetails: cue.zoneDetails,
        durationSeconds: cue.durationSeconds,
        dueAt: Date.now(),
        name: schedule.name
    });

    return { payload: `${fired ? 'Fired' : 'Queued'} ${schedule.qlabCueNumber} (schedule ${scheduleId}: ${schedule.name})` };
})();

const core = global.get('core');
const cronSyncMessages = global.get('cronSyncMessages');
const refreshCueCache = global.get('refreshCueCache');

let schedule;
try {
    const validated = core.scheduling.validateSchedule(msg.payload || {});
    schedule = core.db.schedules.create(core.db.connection, validated);
} catch (err) {
    msg.statusCode = 400;
    msg.payload = { status: 'error', message: err.message };
    return [null, msg];
}

const directives = core.scheduling.cronSync.syncOne(core.db.connection, schedule.id);
const cronMsgs = cronSyncMessages.toCronPlusMessages(directives);

return (async () => {
    const cacheResult = await refreshCueCache(core, schedule.qlabCueNumber);
    if (cacheResult && cacheResult.error) {
        node.warn(`cue_cache refresh failed for ${schedule.qlabCueNumber}: ${cacheResult.error}`);
    }
    if (cacheResult && Array.isArray(cacheResult.unmappedLeafCues) && cacheResult.unmappedLeafCues.length > 0) {
        for (const { cueNumber: unmappedCue, patchId } of cacheResult.unmappedLeafCues) {
            node.warn(`cue ${unmappedCue} (referenced via ${schedule.qlabCueNumber}) is on patch ${patchId}, which isn't mapped to any zone in config/audio-patch-map.json`);
        }
    }

    msg.statusCode = 201;
    msg.payload = { status: 'success', schedule };
    return [cronMsgs, msg];
})();

const core = global.get('core');
const cronSyncMessages = global.get('cronSyncMessages');
const refreshCueCache = global.get('refreshCueCache');
const id = Number(msg.req.params.id);

let schedule;
try {
    const validated = core.scheduling.validateSchedule(msg.payload || {});
    schedule = core.db.schedules.update(core.db.connection, id, validated);
} catch (err) {
    msg.statusCode = 400;
    msg.payload = { status: 'error', message: err.message };
    return [null, msg];
}

if (!schedule) {
    msg.statusCode = 404;
    msg.payload = { status: 'error', message: `Schedule ${id} not found` };
    return [null, msg];
}

const directives = core.scheduling.cronSync.syncOne(core.db.connection, id);
const cronMsgs = cronSyncMessages.toCronPlusMessages(directives);

return (async () => {
    const cacheResult = await refreshCueCache(core, schedule.qlabCueNumber);
    if (cacheResult && cacheResult.error) {
        node.warn(`cue_cache refresh failed for ${schedule.qlabCueNumber}: ${cacheResult.error}`);
    }
    if (cacheResult && Array.isArray(cacheResult.unmappedLeafCues) && cacheResult.unmappedLeafCues.length > 0) {
        for (const { cueNumber: unmappedCue, patchId } of cacheResult.unmappedLeafCues) {
            node.warn(`cue ${unmappedCue} (referenced via ${schedule.qlabCueNumber}) is on patch ${patchId}, which isn't mapped to any zone in config/audio-patch-map.json`);
        }
    }

    msg.statusCode = 200;
    msg.payload = { status: 'success', schedule };
    return [cronMsgs, msg];
})();

const core = global.get('core');
const id = Number(msg.req.params.id);

const existing = core.db.schedules.getById(core.db.connection, id);
if (!existing) {
    msg.statusCode = 404;
    msg.payload = { status: 'error', message: `Schedule ${id} not found` };
    return [null, msg];
}

const removeMsg = { payload: core.scheduling.cronSync.toRemoveCommand(id) };
core.db.schedules.remove(core.db.connection, id);

msg.statusCode = 200;
msg.payload = { status: 'success' };
return [[removeMsg], msg];

const core = global.get('core');
const cronSyncMessages = global.get('cronSyncMessages');
const id = Number(msg.req.params.id);

const existing = core.db.schedules.getById(core.db.connection, id);
if (!existing) {
    msg.statusCode = 404;
    msg.payload = { status: 'error', message: `Schedule ${id} not found` };
    return [null, msg];
}

const schedule = core.db.schedules.setEnabled(core.db.connection, id, !existing.enabled);

const directives = core.scheduling.cronSync.syncOne(core.db.connection, id);
const cronMsgs = cronSyncMessages.toCronPlusMessages(directives);

msg.statusCode = 200;
msg.payload = { status: 'success', schedule };
return [cronMsgs, msg];

const core = global.get('core');
const schedules = core.db.schedules.listEnabled(core.db.connection);
const from = new Date();

const nextOccurrences = {};
for (const s of schedules) {
    const occurrences = core.scheduling.occurrenceCalculator.nextOccurrences(s, from, 1);
    nextOccurrences[s.id] = occurrences[0] ? occurrences[0].toISOString() : null;
}

msg.statusCode = 200;
msg.payload = { status: 'success', nextOccurrences };
return msg;

const core = global.get('core');
const refreshCueCache = global.get('refreshCueCache');
const p = msg.payload || {};

if (!p.name || !p.qlabCueNumber) {
    msg.statusCode = 400;
    msg.payload = { status: 'error', message: 'name and qlabCueNumber are required' };
    return msg;
}

const vogMessage = core.db.vogMessages.create(core.db.connection, {
    name: p.name,
    qlabCueNumber: p.qlabCueNumber,
    enabled: p.enabled !== false
});

return (async () => {
    const cacheResult = await refreshCueCache(core, vogMessage.qlabCueNumber);
    if (cacheResult && cacheResult.error) {
        node.warn(`cue_cache refresh failed for ${vogMessage.qlabCueNumber}: ${cacheResult.error}`);
    }
    if (cacheResult && Array.isArray(cacheResult.unmappedLeafCues) && cacheResult.unmappedLeafCues.length > 0) {
        for (const { cueNumber: unmappedCue, patchId } of cacheResult.unmappedLeafCues) {
            node.warn(`cue ${unmappedCue} (referenced via ${vogMessage.qlabCueNumber}) is on patch ${patchId}, which isn't mapped to any zone in config/audio-patch-map.json`);
        }
    }

    msg.statusCode = 201;
    msg.payload = { status: 'success', vogMessage };
    return msg;
})();

const core = global.get('core');
const refreshCueCache = global.get('refreshCueCache');
const id = Number(msg.req.params.id);
const p = msg.payload || {};

if (!p.name || !p.qlabCueNumber) {
    msg.statusCode = 400;
    msg.payload = { status: 'error', message: 'name and qlabCueNumber are required' };
    return msg;
}

const vogMessage = core.db.vogMessages.update(core.db.connection, id, {
    name: p.name,
    qlabCueNumber: p.qlabCueNumber,
    enabled: p.enabled !== false
});

if (!vogMessage) {
    msg.statusCode = 404;
    msg.payload = { status: 'error', message: `VOG message ${id} not found` };
    return msg;
}

return (async () => {
    const cacheResult = await refreshCueCache(core, vogMessage.qlabCueNumber);
    if (cacheResult && cacheResult.error) {
        node.warn(`cue_cache refresh failed for ${vogMessage.qlabCueNumber}: ${cacheResult.error}`);
    }
    if (cacheResult && Array.isArray(cacheResult.unmappedLeafCues) && cacheResult.unmappedLeafCues.length > 0) {
        for (const { cueNumber: unmappedCue, patchId } of cacheResult.unmappedLeafCues) {
            node.warn(`cue ${unmappedCue} (referenced via ${vogMessage.qlabCueNumber}) is on patch ${patchId}, which isn't mapped to any zone in config/audio-patch-map.json`);
        }
    }

    msg.statusCode = 200;
    msg.payload = { status: 'success', vogMessage };
    return msg;
})();

const core = global.get('core');
const id = Number(msg.req.params.id);

const existing = core.db.vogMessages.getById(core.db.connection, id);
if (!existing) {
    msg.statusCode = 404;
    msg.payload = { status: 'error', message: `VOG message ${id} not found` };
    return msg;
}

core.db.vogMessages.remove(core.db.connection, id);
msg.statusCode = 200;
msg.payload = { status: 'success' };
return msg;

const core = global.get('core');
const id = Number(msg.req.params.id);

const existing = core.db.vogMessages.getById(core.db.connection, id);
if (!existing) {
    msg.statusCode = 404;
    msg.payload = { status: 'error', message: `VOG message ${id} not found` };
    return msg;
}

const vogMessage = core.db.vogMessages.setEnabled(core.db.connection, id, !existing.enabled);

msg.statusCode = 200;
msg.payload = { status: 'success', vogMessage };
return msg;

const core = global.get('core');
const id = Number(msg.req.params.id);

const vogMessage = core.db.vogMessages.getById(core.db.connection, id);
if (!vogMessage) {
    msg.statusCode = 404;
    msg.payload = { status: 'error', message: `VOG message ${id} not found` };
    return msg;
}

if (!vogMessage.enabled) {
    msg.statusCode = 400;
    msg.payload = { status: 'error', message: 'VOG message is disabled - enable it before triggering' };
    return msg;
}

if (!core.health.isArmed()) {
    msg.statusCode = 503;
    msg.payload = { status: 'error', message: 'qlab_disconnected' };
    return msg;
}

// Stops everything currently playing in this VOG cue's own auto-derived zone scope, drops
// anything queued there (no requeue), then plays the VOG cue into that same scope - see
// lib/vog/vogInterruptHandler.js and ADR 0001 decision 9.
return (async () => {
    const { fired, zones } = await core.vog.trigger(vogMessage);
    msg.statusCode = 200;
    msg.payload = { status: 'success', fired, zones };
    return msg;
})();

const core = global.get('core');

return (async () => {
    try {
        const cues = await core.osc.protocol.listCues();
        msg.statusCode = 200;
        msg.payload = { status: 'success', cues };
    } catch (err) {
        msg.statusCode = 503;
        msg.payload = { status: 'error', message: err.message };
    }
    return msg;
})();

const core = global.get('core');
const refreshCueCache = global.get('refreshCueCache');
const id = Number(msg.req.params.id);

const schedule = core.db.schedules.getById(core.db.connection, id);
if (!schedule) {
    msg.statusCode = 404;
    msg.payload = { status: 'error', message: `Schedule ${id} not found` };
    return msg;
}

if (!core.health.isArmed()) {
    msg.statusCode = 503;
    msg.payload = { status: 'error', message: 'qlab_disconnected' };
    return msg;
}

// Goes through the exact same zoneQueueEngine as a real schedule fire - a UI convenience
// button isn't allowed to be the one thing that can overlap audio (see plan / ADR 0001).
// No dedupeKey: play-now never stale-drops anything and is never stale-dropped itself.
return (async () => {
    const cue = await refreshCueCache(core, schedule.qlabCueNumber);
    if (cue.error) {
        msg.statusCode = 502;
        msg.payload = { status: 'error', message: `Could not resolve cue from QLab: ${cue.error}` };
        return msg;
    }
    if (Array.isArray(cue.unmappedLeafCues) && cue.unmappedLeafCues.length > 0) {
        for (const { cueNumber: unmappedCue, patchId } of cue.unmappedLeafCues) {
            node.warn(`cue ${unmappedCue} (referenced via ${schedule.qlabCueNumber}) is on patch ${patchId}, which isn't mapped to any zone in config/audio-patch-map.json`);
        }
    }

    const { fired } = await core.queue.enqueue({
        id: `playnow-${id}-${Date.now()}`,
        scheduleId: id,
        cueNumber: schedule.qlabCueNumber,
        qlabInternalId: cue.qlabInternalId,
        zones: cue.zones,
        zoneDetails: cue.zoneDetails,
        durationSeconds: cue.durationSeconds,
        dueAt: Date.now(),
        name: schedule.name
    });

    msg.statusCode = 200;
    msg.payload = { status: 'success', queued: !fired };
    return msg;
})();

const core = global.get('core');
msg.statusCode = 200;
msg.payload = { status: 'success', state: core.health.getState(), armed: core.health.isArmed() };
return msg;

const core = global.get('core');
const cronSyncMessages = global.get('cronSyncMessages');
const enabled = !!(msg.payload && msg.payload.enabled);

const schedules = core.db.schedules.listAll(core.db.connection);
for (const schedule of schedules) {
    core.db.schedules.setEnabled(core.db.connection, schedule.id, enabled);
}

// One rebuildAll rather than N syncOne calls - it always wipes every dynamic
// cron-plus job first (idempotent by construction, same as fn_startup's own use),
// so this stays correct however many schedules exist.
const directives = core.scheduling.cronSync.rebuildAll(core.db.connection);
const cronMsgs = cronSyncMessages.toCronPlusMessages(directives);

msg.statusCode = 200;
msg.payload = { status: 'success', updated: schedules.length, enabled };
return [cronMsgs, msg];

const core = global.get('core');
const enabled = !!(msg.payload && msg.payload.enabled);

// VOG messages are manual-trigger only (no cron-plus sync involved), so this is
// just a per-row setEnabled loop - unlike the schedules equivalent, there's no
// scheduler state to rebuild afterward.
const vogMessages = core.db.vogMessages.listAll(core.db.connection);
for (const vogMessage of vogMessages) {
    core.db.vogMessages.setEnabled(core.db.connection, vogMessage.id, enabled);
}

msg.statusCode = 200;
msg.payload = { status: 'success', updated: vogMessages.length, enabled };
return msg;

const core = global.get('core');
const refreshCueCache = global.get('refreshCueCache');
const refreshAllReferencedCues = global.get('refreshAllReferencedCues');

return (async () => {
    const results = await refreshAllReferencedCues(core, refreshCueCache);
    const failures = Object.entries(results).filter(([, r]) => r && r.error);
    if (failures.length > 0) {
        node.warn(`Periodic cue_cache refresh: ${failures.length} cue(s) failed`);
    }
    for (const [cueNumber, result] of Object.entries(results)) {
        if (result && Array.isArray(result.unmappedLeafCues) && result.unmappedLeafCues.length > 0) {
            for (const { cueNumber: unmappedCue, patchId } of result.unmappedLeafCues) {
                node.warn(`cue ${unmappedCue} (referenced via ${cueNumber}) is on patch ${patchId}, which isn't mapped to any zone in config/audio-patch-map.json`);
            }
        }
    }
    return null;
})();

const core = global.get('core');
const refreshCueCache = global.get('refreshCueCache');
const refreshAllReferencedCues = global.get('refreshAllReferencedCues');

return (async () => {
    const results = await refreshAllReferencedCues(core, refreshCueCache);
    const failed = Object.entries(results)
        .filter(([, r]) => r && r.error)
        .map(([cueNumber]) => cueNumber);

    for (const [cueNumber, result] of Object.entries(results)) {
        if (result && Array.isArray(result.unmappedLeafCues) && result.unmappedLeafCues.length > 0) {
            for (const { cueNumber: unmappedCue, patchId } of result.unmappedLeafCues) {
                node.warn(`cue ${unmappedCue} (referenced via ${cueNumber}) is on patch ${patchId}, which isn't mapped to any zone in config/audio-patch-map.json`);
            }
        }
    }

    msg.statusCode = 200;
    msg.payload = {
        status: 'success',
        refreshedCount: Object.keys(results).length - failed.length,
        failed
    };
    return msg;
})();

const core = global.get('core');
const since = msg.req.query.since || null;

msg.statusCode = 200;
msg.payload = { status: 'success', events: core.queue.getRecentEvents(since) };
return msg;

const core = global.get('core');
const zonesAdmin = global.get('zonesAdmin');

msg.statusCode = 200;
msg.payload = { status: 'success', zones: zonesAdmin.getZonesSnapshot(core) };
return msg;

const core = global.get('core');

return (async () => {
    try {
        const patches = await core.osc.protocol.getAudioPatches();
        // 1-based index, matching /cue/{n}/patch's own indexing convention
        const withIds = patches.map((patch, i) => ({ patchId: String(i + 1), name: patch.name }));
        msg.statusCode = 200;
        msg.payload = { status: 'success', patches: withIds };
    } catch (err) {
        msg.statusCode = 503;
        msg.payload = { status: 'error', message: err.message };
    }
    return msg;
})();

const core = global.get('core');
const deriveZoneSuggestion = global.get('deriveZoneSuggestion');
const cueNumber = msg.req.query.cueNumber;

if (!cueNumber) {
    msg.statusCode = 400;
    msg.payload = { status: 'error', message: 'cueNumber query parameter is required' };
    return msg;
}

return (async () => {
    // A live patch lookup can fail for reasons that have nothing to do with the
    // convention-based suggestion below (the cue doesn't exist yet, it's a Group
    // with no /patch of its own, QLab is briefly unreachable) - none of that should
    // block the naming-convention autofill, which needs nothing from QLab at all.
    // patchId simply comes back null in that case; this endpoint only ever 5xxs on
    // its own malformed input, never on QLab denying/timing out a query.
    let patchId = null;
    try {
        const rawPatchId = await core.osc.protocol.getCuePatch(cueNumber);
        patchId = (rawPatchId === null || rawPatchId === undefined) ? null : String(rawPatchId);
    } catch (err) {
        patchId = null;
    }

    const suggestion = { patchId, ...(deriveZoneSuggestion(cueNumber) || {}) };

    msg.statusCode = 200;
    msg.payload = { status: 'success', ...suggestion };
    return msg;
})();

const core = global.get('core');
const zonesAdmin = global.get('zonesAdmin');
const p = msg.payload || {};

if (!p.zoneName || typeof p.zoneName !== 'string' || !p.zoneName.trim()) {
    msg.statusCode = 400;
    msg.payload = { status: 'error', message: 'zoneName is required' };
    return msg;
}

if (core.zones.config.has(p.zoneName)) {
    msg.statusCode = 409;
    msg.payload = { status: 'error', message: `Zone "${p.zoneName}" already exists` };
    return msg;
}

const zones = zonesAdmin.buildZonesObject(core);
zones[p.zoneName] = {
    messagingPatchId: p.messagingPatchId,
    duckCueNumber: p.duckCueNumber,
    unduckCueNumber: p.unduckCueNumber
};

try {
    core.zones.save(zones);
} catch (err) {
    msg.statusCode = 400;
    msg.payload = { status: 'error', message: err.message };
    return msg;
}

msg.statusCode = 201;
msg.payload = { status: 'success', zoneName: p.zoneName };
return msg;

const core = global.get('core');
const zonesAdmin = global.get('zonesAdmin');
const zoneName = msg.req.params.zoneName;
const p = msg.payload || {};

if (!core.zones.config.has(zoneName)) {
    msg.statusCode = 404;
    msg.payload = { status: 'error', message: `Zone "${zoneName}" not found` };
    return msg;
}

const zones = zonesAdmin.buildZonesObject(core);
zones[zoneName] = {
    messagingPatchId: p.messagingPatchId,
    duckCueNumber: p.duckCueNumber,
    unduckCueNumber: p.unduckCueNumber
};

try {
    core.zones.save(zones);
} catch (err) {
    msg.statusCode = 400;
    msg.payload = { status: 'error', message: err.message };
    return msg;
}

msg.statusCode = 200;
msg.payload = { status: 'success', zoneName };
return msg;

const core = global.get('core');
const zonesAdmin = global.get('zonesAdmin');
const zoneName = msg.req.params.zoneName;

if (!core.zones.config.has(zoneName)) {
    msg.statusCode = 404;
    msg.payload = { status: 'error', message: `Zone "${zoneName}" not found` };
    return msg;
}

const zones = zonesAdmin.buildZonesObject(core);
delete zones[zoneName];

try {
    core.zones.save(zones);
} catch (err) {
    msg.statusCode = 400;
    msg.payload = { status: 'error', message: err.message };
    return msg;
}

msg.statusCode = 200;
msg.payload = { status: 'success', zoneName };
return msg;

const core = global.get('core');

msg.statusCode = 200;
msg.payload = { status: 'success', ...core.queue.getState() };
return msg;

const core = global.get('core');
const zone = msg.req.query.zone;
const offset = Number(msg.req.query.offset || 0);
const count = Number(msg.req.query.count || 25);

if (!zone) {
    msg.statusCode = 400;
    msg.payload = { status: 'error', message: 'zone is required' };
    return msg;
}

// A schedule's own next-due moment is already represented by a live occupancy/queued
// entry in this zone (see zoneUpcomingOccurrences.js's dedupe) - collect those schedule
// ids so the projection doesn't show that same due moment a second time.
const state = core.queue.getState();
const liveEntries = [
    ...(state.queued[zone] || []),
    ...(state.occupancy[zone] ? [state.occupancy[zone].entry] : [])
];
const liveScheduleIds = new Set(liveEntries.map((e) => e.scheduleId).filter((id) => id != null));

const result = core.scheduling.zoneUpcomingOccurrences.getUpcomingOccurrencesForZone(
    core.db.connection,
    zone,
    {
        schedulesRepo: core.db.schedules,
        cueCacheRepo: core.db.cueCache,
        nextOccurrences: core.scheduling.occurrenceCalculator.nextOccurrences
    },
    { offset, count, liveScheduleIds }
);

msg.statusCode = 200;
msg.payload = { status: 'success', zone, ...result };
return msg;
